import { createRequestContext, createResponseContext, HttpMiddlewarePipeline } from "@zudojs/http";

let routeCalls = 0;
const pipeline = new HttpMiddlewarePipeline();
pipeline.use(async (context, next) => {
  if (context.request.method !== "GET") {
    return context.response.setStatus(503).json({ error: "read-only today" });
  }
  return next();
});
pipeline.use(async (context) => {
  routeCalls += 1;
  return context.response.json({ ok: true });
});

const post = await pipeline.execute(createRequestContext({ method: "POST", url: "/tasks" }), createResponseContext());
const get = await pipeline.execute(createRequestContext({ method: "GET", url: "/tasks" }), createResponseContext());
console.log(post.status, get.status, routeCalls);

