const strictLimit = async (method, next) => "limited";

function onlyWrites(middleware) {
  return (method, next) =>
    ["GET", "HEAD", "OPTIONS"].includes(method) ? next() : middleware(method, next);
}

const limitWrites = onlyWrites(strictLimit);
const results = [];
for (const method of ["GET", "POST", "DELETE", "OPTIONS"]) {
  results.push(`${method}:${await limitWrites?.(method, async () => "ok")}`);
}
console.log(results.join(" "));
